mapper.select:
SELECT id, knowledge_key, title, category, content, embedding_status, version_no, status, create_time, update_time FROM ai_knowledge WHERE status = 1
AND (knowledge_key LIKE CONCAT('%', #{keyword}, '%') OR title LIKE CONCAT('%', #{keyword}, '%'))
AND category = #{category}
AND embedding_status = #{embeddingStatus}
ORDER BY update_time DESC, id DESC

mapper.update:
UPDATE ai_knowledge
SET status = 0,
    update_time = #{updateTime}
WHERE id = #{id}
  AND status = 1

mapper.select:
SELECT id, title, category, content, embedding
FROM ai_knowledge
WHERE status = 1
  AND embedding_status = 1
  AND embedding_model = #{embeddingModel}
  AND embedding_dimensions = #{embeddingDimensions}

mapper.update:
UPDATE ai_knowledge
SET embedding_status = 2,
    update_time = #{now}
WHERE id = #{id}
  AND status = 1
  AND embedding_status = 0

mapper.select:
SELECT COUNT(DISTINCT knowledge_key)
FROM ai_knowledge
WHERE status = 1
  AND embedding_status = 1
  AND embedding_model = #{embeddingModel}
  AND embedding_dimensions = #{embeddingDimensions}
  AND knowledge_key IN

      #{knowledgeKey}
